import React, { useState } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';

export default function UploadModal({ isOpen, onClose, onPredictionResult }) {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleUpload = async () => {
    if (!file) return;
    setLoading(true);
    setError('');
    
    const formData = new FormData();
    formData.append('file', file);
    
    try {
      const response = await fetch('http://localhost:8000/api/predict', {
        method: 'POST',
        body: formData,
      });
      
      const data = await response.json();
      if (data.error) {
        setError(data.error);
      } else {
        onPredictionResult(data, file);
        onClose();
      }
    } catch (err) {
      setError('Failed to connect to backend AI server. Make sure it is running on port 8000.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden relative">
        <div className="flex justify-between items-center p-4 border-b">
          <h2 className="font-bold text-lg text-slate-800">Analyze New SAR Image</h2>
          <button onClick={onClose} className="p-1 hover:bg-slate-100 rounded">
            <X className="w-5 h-5 text-slate-500" />
          </button>
        </div>
        
        <div className="p-6 space-y-4">
          <div className="border-2 border-dashed border-slate-300 rounded-lg p-8 flex flex-col items-center justify-center text-center cursor-pointer hover:bg-slate-50 transition"
               onClick={() => document.getElementById('file-upload').click()}>
            <Upload className="w-8 h-8 text-sky-500 mb-2" />
            <p className="text-sm font-medium text-slate-700">Click to upload SAR Image</p>
            <p className="text-xs text-slate-500 mt-1">PNG, JPG, TIFF</p>
            <input 
              id="file-upload" 
              type="file" 
              className="hidden" 
              accept="image/*"
              onChange={(e) => setFile(e.target.files[0])} 
            />
          </div>
          
          {file && (
            <div className="text-sm text-emerald-600 font-medium">
              Selected: {file.name}
            </div>
          )}
          
          {error && (
            <div className="text-sm text-red-600 bg-red-50 p-2 rounded border border-red-200">
              {error}
            </div>
          )}
        </div>
        
        <div className="p-4 border-t bg-slate-50 flex justify-end">
          <button 
            onClick={handleUpload}
            disabled={!file || loading}
            className="px-4 py-2 bg-sky-600 text-white rounded-lg font-medium text-sm disabled:opacity-50 flex items-center gap-2"
          >
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            {loading ? 'Analyzing with CBDNet...' : 'Run Analysis'}
          </button>
        </div>
      </div>
    </div>
  );
}
